pages.schema:
{
  "@context": "https://schema.org",
  "@type": "HowTo",
  "name": "Wie man Bilder mit CovertConvert konvertiert",
  "description": "Konvertieren Sie HEIC, WebP, AVIF und andere Bildformate vollständig in Ihrem Browser zu JPG oder PNG.",
  "step": [
    {
      "@type": "HowToStep",
      "name": "Dateien auswählen",
      "text": "Legen Sie Bilddateien auf den Konverter oder klicken Sie zum Durchsuchen. Unterstützt HEIC, WebP, AVIF, TIFF, PNG, BMP und GIF."
    },
    {
      "@type": "HowToStep",
      "name": "Ausgabeformat wählen",
      "text": "Wählen Sie JPEG für kleinere Dateien oder PNG für verlustfreie Qualität. Passen Sie die JPEG-Qualität nach Wunsch an."
    },
    {
      "@type": "HowToStep",
      "name": "Konvertierung erfolgt lokal",
      "text": "Ihr Browser verarbeitet die Bilder mit WebAssembly. Dateien verlassen nie Ihr Gerät."
    },
    {
      "@type": "HowToStep",
      "name": "Ergebnisse herunterladen",
      "text": "Konvertierte Dateien werden automatisch heruntergeladen. Mehrere Dateien werden in einem ZIP-Archiv gebündelt."
    }
  ]
}
